import Image from "next/image";
import React from "react";
import { Heading } from "./Heading";
import { twMerge } from "tailwind-merge";

interface TechItem {
  title: string;
  src: string;
  className: string;
  invertOnDark?: boolean;
  useImgTag?: boolean; // ✅ for remote SVG endpoints that Next/Image struggles with
}

const devicon = (path: string) =>
  `https://cdn.jsdelivr.net/gh/devicons/devicon/icons/${path}`;

const simpleIcon = (name: string) =>
  `https://cdn.jsdelivr.net/npm/simple-icons@v11/icons/${name}.svg`;

/**
 * SkillIcons (SVG is generated by a worker; Next/Image sometimes fails to render)
 * We'll render these with <img> instead.
 */
const skillIcon = (name: string) =>
  `https://skillicons.dev/icons?i=${encodeURIComponent(name)}`;

export const TechStack = () => {
  const techCategories: {
    [key: string]: {
      title: string;
      items: TechItem[];
    };
  } = {
    core: {
      title: "Core Stack",
      items: [
        // Languages
        {
          title: "TypeScript",
          src: devicon("typescript/typescript-original.svg"),
          className: "h-10 w-10",
        },
        {
          title: "Python",
          src: devicon("python/python-original.svg"),
          className: "h-10 w-10",
        },

        // Frontend
        {
          title: "Next.js",
          src: devicon("nextjs/nextjs-original.svg"),
          className: "h-10 w-10",
          invertOnDark: true,
        },
        {
          title: "React",
          src: devicon("react/react-original.svg"),
          className: "h-10 w-10",
        },
        {
          title: "Tailwind",
          src: devicon("tailwindcss/tailwindcss-original.svg"),
          className: "h-10 w-10",
        },

        // Backend
        {
          title: "Node.js",
          src: devicon("nodejs/nodejs-original.svg"),
          className: "h-10 w-10",
        },
        {
          title: "Express",
          src: devicon("express/express-original.svg"),
          className: "h-10 w-10",
          invertOnDark: true,
        },
        {
          title: "GraphQL",
          src: devicon("graphql/graphql-plain.svg"),
          className: "h-10 w-10",
        },

        // Data
        {
          title: "MongoDB",
          src: devicon("mongodb/mongodb-original.svg"),
          className: "h-10 w-10",
        },
        {
          title: "PostgreSQL",
          src: devicon("postgresql/postgresql-original.svg"),
          className: "h-10 w-10",
        },
        {
          title: "Redis",
          src: devicon("redis/redis-original.svg"),
          className: "h-10 w-10",
        },

        // Cloud / Ops
        {
          title: "AWS",
          src: simpleIcon("amazonaws"),
          className: "h-10 w-10",
          invertOnDark: true,
        },
        {
          title: "Docker",
          src: devicon("docker/docker-original.svg"),
          className: "h-10 w-10",
        },
        {
          title: "Git",
          src: devicon("git/git-original.svg"),
          className: "h-10 w-10",
        },

        // ✅ AI (ONLY OpenAI for now)
        {
          title: "OpenAI API",
          src: simpleIcon("openai"),
          className: "h-10 w-10",
          invertOnDark: true,
        },
      ],
    },

    alsoUse: {
      title: "Also Use",
      items: [
        {
          title: "FastAPI",
          src: devicon("fastapi/fastapi-original.svg"),
          className: "h-10 w-10",
          invertOnDark: true,
        },
        {
          title: "NestJS",
          src: devicon("nestjs/nestjs-original.svg"),
          className: "h-10 w-10",
        },
        {
          title: "Prisma",
          src: devicon("prisma/prisma-original.svg"),
          className: "h-10 w-10",
          invertOnDark: true,
        },
        {
          title: "Vercel",
          src: devicon("vercel/vercel-original.svg"),
          className: "h-10 w-10",
          invertOnDark: true,
        },
        {
          title: "Remix",
          src: devicon("remix/remix-original.svg"),
          className: "h-10 w-10",
          invertOnDark: true,
        },
        {
          title: "Framer Motion",
          src: devicon("framermotion/framermotion-original.svg"),
          className: "h-10 w-10",
          invertOnDark: true,
        },
        {
          title: "Figma",
          src: devicon("figma/figma-original.svg"),
          className: "h-10 w-10",
        },
      ],
    },
  };

  return (
    <div>
      <Heading
        as="h2"
        className="font-black text-lg md:text-lg lg:text-lg mt-20 mb-4"
      >
        Tech I&apos;m Using
      </Heading>

      <div className="space-y-8">
        {Object.entries(techCategories).map(([key, category]) => (
          <div
            key={key}
            className="animate-in fade-in slide-in-from-bottom-4 duration-500"
          >
            <h3 className="text-sm font-semibold text-neutral-600 dark:text-neutral-400 mb-3 uppercase tracking-wider">
              {category.title}
            </h3>

            <div className="flex flex-row flex-wrap gap-4">
              {category.items.map((item, index) => (
                <div
                  key={item.title}
                  className="flex flex-col items-center gap-2 p-3 rounded-lg hover:bg-neutral-50 dark:hover:bg-neutral-800 transition-all duration-200 group hover:scale-105 active:scale-95 animate-in fade-in slide-in-from-bottom-2 duration-300"
                  style={{ animationDelay: `${index * 100}ms` }}
                >
                  {/* ✅ Use <img> for SkillIcons (remote worker-generated SVG) */}
                  {item.useImgTag ? (
                    <img
                      src={item.src}
                      alt={item.title}
                      className={twMerge(
                        "object-contain",
                        item.className,
                        item.invertOnDark ? "dark:invert" : ""
                      )}
                      loading="lazy"
                      referrerPolicy="no-referrer"
                    />
                  ) : (
                    <Image
                      src={item.src}
                      width={80}
                      height={80}
                      alt={item.title}
                      className={twMerge(
                        "object-contain",
                        item.className,
                        item.invertOnDark ? "dark:invert" : ""
                      )}
                    />
                  )}

                  <span className="text-xs text-neutral-600 dark:text-neutral-400 group-hover:text-neutral-900 dark:group-hover:text-neutral-200 transition-colors duration-200">
                    {item.title}
                  </span>
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>

      <p className="mt-6 text-xs text-neutral-500 dark:text-neutral-500">
        Icons via Devicon + Simple Icons + SkillIcons.
      </p>
    </div>
  );
};
